// The Actor already returns only jobs it never delivered (onlyNewJobs). Format them; a job found by two searches is kept once.
const seen = new Set();
const out = [];
for (const { json: j } of $input.all()) {
  if (j.found === false) continue;
  const key = [j.title, j.company, j.location].join('|').toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({
    json: {
      jobId: j.jobId,
      title: j.title,
      company: j.company,
      location: j.location,
      employmentType: j.employmentType,
      salary: j.salary,
      salaryMin: j.salaryMin,
      salaryMax: j.salaryMax,
      salaryPeriod: j.salaryPeriod,
      salaryCurrency: j.salaryCurrency,
      postedAt: j.postedAt,
      via: j.via,
      applyUrl: j.applyUrl,
      search: j.query,
      firstSeen: new Date().toISOString().slice(0, 10),
    },
  });
}
return out;
